from datetime import datetime, timedelta
from typing import Any, Optional
from uuid import UUID

from src.database import async_session
from src.models import QoLMetric, CaregiverLoad, SafetyIncident, Appointment
from src.services.digital_twin import DigitalTwinService


class StabilityForecastService:
    """Forecasts family stability trends using historical data and digital twin simulation."""

    def __init__(self):
        self.digital_twin_service = DigitalTwinService()

    async def generate_forecast(self, family_id: UUID, horizon_days: int = 30) -> dict[str, Any]:
        """Generate a stability forecast for the next N days."""

        now = datetime.utcnow()
        since = now - timedelta(days=horizon_days)

        # Gather historical data
        async with async_session() as session:
            # Recent QoL metrics
            qol_result = await session.execute(
                QoLMetric.__table__.select()
                .where(QoLMetric.family_id == family_id)
                .where(QoLMetric.measured_at >= since)
                .order_by(QoLMetric.measured_at)
            )
            qol_metrics = list(qol_result.scalars().all())

            # Caregiver load history
            load_result = await session.execute(
                CaregiverLoad.__table__.select()
                .where(CaregiverLoad.family_id == family_id)
                .where(CaregiverLoad.created_at >= since)
            )
            caregiver_loads = list(load_result.scalars().all())

            # Safety incidents
            incident_result = await session.execute(
                SafetyIncident.__table__.select()
                .where(SafetyIncident.family_id == family_id)
                .where(SafetyIncident.created_at >= since)
            )
            incidents = list(incident_result.scalars().all())

            # Upcoming appointments
            appt_result = await session.execute(
                Appointment.__table__.select()
                .where(Appointment.family_id == family_id)
                .where(Appointment.start_time >= now)
                .where(Appointment.is_recurring == False)
            )
            upcoming = list(appt_result.scalars().all())

        # Compute trend
        trend = self._compute_trend(qol_metrics, caregiver_loads, incidents)

        # Get digital twin projection
        twin_metrics = {
            "qol_scores": [m.metric_value for m in qol_metrics[-7:]] if qol_metrics else [50],
            "caregiver_loads": [l.stress_level for l in caregiver_loads[-7:]] if caregiver_loads else [30],
            "upcoming_events": len(upcoming),
        }
        twin_projection = await self.digital_twin_service.simulate_scenario(
            family_id, "projected_trajectory", {"days": horizon_days}
        )

        # Risk factors
        risk_factors = self._identify_risk_factors(qol_metrics, caregiver_loads, incidents, upcoming)

        # Recommendations
        recommendations = self._generate_recommendations(risk_factors)

        return {
            "family_id": str(family_id),
            "horizon_days": horizon_days,
            "generated_at": now.isoformat(),
            "trend": trend,
            "twin_projection": twin_projection,
            "risk_factors": risk_factors,
            "recommendations": recommendations,
            "metrics_used": {
                "qol_data_points": len(qol_metrics),
                "caregiver_snapshots": len(caregiver_loads),
                "incidents": len(incidents),
                "upcoming_appointments": len(upcoming),
            },
        }

    def _compute_trend(
        self, qol_metrics: list, caregiver_loads: list, incidents: list
    ) -> dict[str, Any]:
        qol_values = [m.metric_value for m in qol_metrics]
        load_values = [l.stress_level for l in caregiver_loads]

        if len(qol_values) >= 2:
            qol_slope = (qol_values[-1] - qol_values[0]) / max(1, len(qol_values) - 1)
        else:
            qol_slope = 0

        if len(load_values) >= 2:
            load_slope = (load_values[-1] - load_values[0]) / max(1, len(load_values) - 1)
        else:
            load_slope = 0

        if qol_slope > 2 and load_slope < -1:
            direction = "improving"
        elif qol_slope < -2 or load_slope > 1:
            direction = "declining"
        else:
            direction = "stable"

        return {
            "direction": direction,
            "qol_slope_per_day": round(qol_slope, 2),
            "load_slope_per_day": round(load_slope, 2),
            "incident_count": len(incidents),
            "confidence": min(0.95, 0.5 + len(qol_metrics) * 0.05),
        }

    def _identify_risk_factors(
        self, qol_metrics: list, caregiver_loads: list, incidents: list, upcoming: list
    ) -> list[dict[str, Any]]:
        factors = []

        # Check for declining QoL
        if len(qol_metrics) >= 3:
            recent_avg = sum(m.metric_value for m in qol_metrics[-3:]) / 3
            older_avg = sum(m.metric_value for m in qol_metrics[:3]) / 3 if len(qol_metrics) >= 6 else recent_avg
