from src.database import async_session
from src.models import Family, FamilyMember, Person, Memory, Event
from src.services.memory_service import MemoryService


class FamilyConnectionService:
    """Analyzes and nurtures family relationships and connections."""

    def __init__(self):
        self.memory_service = MemoryService()

    async def get_family_snapshot(self, family_id: UUID) -> dict[str, Any]:
        """Get a complete snapshot of a family's relational state."""
        async with async_session() as session:
            family_result = await session.execute(
                Family.__table__.select().where(Family.id == family_id)
            )
            family = family_result.scalar_one_or_none()
            if not family:
                return {"error": "Family not found"}

            members_result = await session.execute(
                FamilyMember.__table__.select().where(FamilyMember.family_id == family_id)
            )
            members = list(members_result.scalars().all())

            person_ids = [m.person_id for m in members]
            people_result = await session.execute(
                Person.__table__.select().where(Person.id.in_(person_ids))
            )
            people = {p.id: p for p in people_result.scalars().all()}

        return {
            "family": {"id": family.id, "name": family.name},
            "members": [
                {
                    "id": m.id,
                    "person": {
                        "id": m.person_id,
                        "name": people[m.person_id].full_name if m.person_id in people else "Unknown",
                        "age": people[m.person_id].age if m.person_id in people else None,
                    },
                    "role_in_family": m.role_in_family,
                    "is_primary_contact": m.is_primary_contact,
                }
                for m in members
            ],
            "member_count": len(members),
            "generation_count": self._count_generations(members, people),
        }

    def _count_generations(self, members: list, people: dict) -> int:
        """Estimate generation count from member roles."""
        role_gen_map = {"elder": 1, "parent": 2, "caregiver": 2, "child": 3, "grandchild": 4}
        generations = set()
        for m in members:
            gen = role_gen_map.get(m.role_in_family, 2)
            generations.add(gen)
        return max(1, len(generations))

    async def suggest_connections(self, family_id: UUID) -> list[dict[str, Any]]:
        """Suggest family members who should connect more."""
        snapshot = await self.get_family_snapshot(family_id)
        members = snapshot.get("members", [])
        suggestions = []

        # Find elders who may need more engagement
        for m in members:
            role = m["role_in_family"]
            if role in ("elder", "grandchild"):
