    """Handles scheduling, task assignment, and logistical coordination."""

    def __init__(self):
        super().__init__(name="logistics_agent", version="0.1.0")
        self.memory_service = MemoryService()

    async def process(self, context: dict[str, Any]) -> dict[str, Any]:
        """Process a logistics request."""

        action = context.get("action", "schedule")
        family_id = context.get("family_id")

        if not family_id:
            return {"error": "family_id required", "status": "failed"}

        if action == "schedule":
            return await self._handle_scheduling(context)
        elif action == "assign_task":
            return await self._handle_task_assignment(context)
        elif action == "optimize":
            return await self._handle_optimization(context)
        else:
            return {"error": f"Unknown action: {action}"}

    async def _handle_scheduling(self, context: dict[str, Any]) -> dict[str, Any]:
        """Schedule a new event or appointment."""
        family_id = context["family_id"]
        event_data = {
            "title": context.get("title", "Unnamed Event"),
            "event_type": context.get("event_type", "other"),
            "date": context.get("date", datetime.utcnow() + timedelta(days=7)),
            "location": context.get("location"),
            "priority": context.get("priority", 3),
            "needs_coordination": context.get("needs_coordination", True),
        }

        return {
            "action": "schedule",
            "status": "scheduled",
