from typing import Any
from uuid import UUID

from src.agents.base_agent import BaseAgent
from src.services.family_connection import FamilyConnectionService
from src.services.memory_service import MemoryService


class RelationshipAgent(BaseAgent):
    """Monitors and strengthens family relationships."""

    def __init__(self):
        super().__init__(name="relationship_agent", version="0.1.0")
        self.connection_service = FamilyConnectionService()
        self.memory_service = MemoryService()

    async def process(self, context: dict[str, Any]) -> dict[str, Any]:
        """Analyze relational dynamics and suggest interventions."""

        family_id = context.get("family_id")
        action = context.get("action", "analyze")

        if not family_id:
            return {"error": "family_id required", "status": "failed"}

        snapshot = await self.connection_service.get_family_snapshot(family_id)

        if action == "analyze":
            return await self._analyze_relationships(snapshot, family_id)
        elif action == "suggest":
            return await self._suggest_connections(family_id)
        elif action == "monitor":
            return await self._monitor_dynamics(snapshot)
        else:
            return {"error": f"Unknown action: {action}"}

    async def _analyze_relationships(self, snapshot: dict, family_id: UUID) -> dict[str, Any]:
        """Analyze the current state of family relationships."""
        members = snapshot.get("members", [])

        # Check for isolated members
        isolated = []
        for m in members:
            if m["role_in_family"] in ("elder", "grandchild"):
                isolated.append(m["person"]["name"])

        # Check for role gaps
        expected_roles = {"elder", "parent", "caregiver", "child"}
        present_roles = {m["role_in_family"] for m in members}
        missing_roles = expected_roles - present_roles

        analysis = {
            "member_count": len(members),
            "generation_count": snapshot.get("generation_count", 1),
            "isolated_members": isolated,
            "missing_role_coverage": list(missing_roles),
            "relationship_health": self._compute_health_score(members),
        }

        return analysis

    def _compute_health_score(self, members: list) -> dict[str, Any]:
        score = 70  # base
        penalties = 0
        bonuses = 0

        roles = {m["role_in_family"] for m in members}
        if "caregiver" in roles:
            bonuses += 10
        if not any(m["is_primary_contact"] for m in members):
            penalties += 15

        final = max(0, min(100, score + bonuses - penalties))
        return {
            "score": final,
            "rating": "healthy" if final >= 70 else "needs_attention" if final >= 40 else "critical",
        }

    async def _suggest_connections(self, family_id: UUID) -> dict[str, Any]:
        suggestions = await self.connection_service.suggest_connections(family_id)
        return {"suggestions": suggestions}

    async def _monitor_dynamics(self, snapshot: dict) -> dict[str, Any]:
        return {
            "current_state": "stable",
            "recent_changes": [],
            "alerts": [],
        }", "path": "/home/azureuser/fscompanion/src/agents/relationship_agent.py"}

{"content": """"Drift watcher — detects when agent outputs diverge from expected behavior."""

from datetime import datetime, timedelta
from typing import Any
from uuid import UUID

from src.agents.base_agent import BaseAgent
from src.config import settings
from src.services.memory_service import MemoryService
from src.services.sealed_calibration import SealedCalibrationService


class DriftWatcher(BaseAgent):
    """Monitors all agents for behavioral drift and calibration issues."""

    def __init__(self):
        super().__init__(name="drift_watcher", version="0.1.0")
        self.memory_service = MemoryService()
        self.calibration_service = SealedCalibrationService()

    async def process(self, context: dict[str, Any]) -> dict[str, Any]:
        """Check for drift across specified or all agents."""

        family_id = context.get("family_id")
        agent_name = context.get("agent_name")
        check_window_hours = context.get("window_hours", 24)

        if not family_id:
            return {"error": "family_id required", "status": "failed"}

        since = datetime.utcnow() - timedelta(hours=check_window_hours)

        # Search for recent calibration events
        memories = await self.memory_service.search_memories(family_id, "calibration", limit=50)
        recent_calibrations = [m for m in memories if m.created_at >= since]

        analysis = {
            "family_id": family_id,
            "check_window_hours": check_window_hours,
            "total_calibrations": len(recent_calibrations),
            "drift_detected": False,
            "agents_checked": [],
        }

        # Analyze calibration patterns
        agent_drift_scores: dict[str, float] = {}
        for mem in recent_calibrations:
            agent = mem.source_agent
            if agent not in agent_drift_scores:
                agent_drift_scores[agent] = 1.0
            # Decrease confidence for each calibration needed
            if "contradiction" in (mem.context or "").lower():
                agent_drift_scores[agent] -= 0.1

        # Flag agents below threshold
        for agent, score in agent_drift_scores.items():
            if agent_name and agent != agent_name:
                continue
            entry = {
                "agent": agent,
                "drift_score": round(max(0, score), 2),
                "status": "drifting" if score < 0.7 else "stable",
            }
            analysis["agents_checked"].append(entry)
            if score < 0.7:
                analysis["drift_detected"] = True

        analysis["recommendations"] = self._generate_recommendations(analysis["agents_checked"])

        return analysis

    def _generate_recommendations(self, agent_statuses: list[dict]) -> list[str]:
        recommendations = []
        for status in agent_statuses:
            if status["status"] == "drifting":
                recommendations.append(
                    f"Recalibrate {status['agent']}: drift score {status['drift_score']}. "
                    f"Review recent outputs for consistency."
                )
        if not recommendations:
            recommendations.append("All agents are within acceptable calibration ranges.")
        return recommendations

    async def watch_loop(self, family_id: UUID, interval_seconds: int = 300) -> dict[str, Any]:
        """Run a continuous drift monitoring cycle."""
        return await self.process({"family_id": family_id, "window_hours": 1})", "path": "/home/azureuser/fscompanion/src/agents/drift_watcher.py"}

