from typing import Any


class SafetyFilter:
    """Filters Gemma responses to prevent harmful or inappropriate content."""

    BLOCKED_CATEGORIES = {
        "self_harm": ["self-harm", "suicide", "kill yourself", "end it all"],
        "harm_to_others": ["hurt", "attack", "kill", "harm", "violence"],
        "medical_advice": ["diagnose", "prescribe", "treatment", "medication dosage"],
        "legal_advice": ["sue", "lawsuit", "legal action", "court"],
        "financial_advice": ["invest", "stocks", "financial product", "guarantee"],
    }

    WARNING_KEYWORDS = {
        "crisis": ["crisis", "emergency", "urgent", "immediate danger"],
        "escalation_needed": ["police", "911", "hospital", "emergency services"],
        "burnout_signal": ["overwhelmed", "can't take it", "giving up", "exhausted"],
    }

    def __init__(self):
        self.violations: list[dict[str, Any]] = []

    def filter(self, response: str, context: dict[str, Any] | None = None) -> tuple[str, list[dict]]:
        """Filter a response and return (cleaned_response, violations)."""

        self.violations = []
        cleaned = response
        family_context = context or {}

        # Check for blocked content
        for category, keywords in self.BLOCKED_CATEGORIES.items():
            for keyword in keywords:
                if keyword.lower() in response.lower():
                    self.violations.append({
                        "category": category,
                        "keyword": keyword,
                        "severity": "high" if category in ("self_harm", "harm_to_others") else "medium",
                        "action": "redacted",
                    })
                    cleaned = self._redact_section(cleaned, keyword)

        # Check for warnings
        warnings = []
        for category, keywords in self.WARNING_KEYWORDS.items():
            for keyword in keywords:
                if keyword.lower() in response.lower():
                    warnings.append({
                        "category": category,
                        "keyword": keyword,
                        "action": "flagged",
                    })

        # Add safety preamble if violations found
        if self.violations:
            preamble = (
                "⚠️ I want to make sure your family stays safe. "
                "Some content has been filtered. If you or someone you know "
                "is in immediate danger, please contact emergency services right away.\n\n"
            )
            cleaned = preamble + cleaned

        # Check for crisis context in family info
        if family_context.get("crisis_flag"):
            crisis_notice = (
                "\n\n🚨 CRISIS RESOURCES:\n"
                "If you or a family member is in immediate danger:\n"
                "  • Call 911 or your local emergency number\n"
                "  • Contact the Crisis Text Line: text HOME to 741741\n"
                "  • National Suicide Prevention Lifeline: 988\n"
            )
            cleaned += crisis_notice

        return cleaned, self.violations + [{"category": "warning", **w} for w in warnings]

    def _redact_section(self, text: str, keyword: str) -> str:
        """Redact sections containing harmful keywords."""
        import re
        # Remove sentences containing the keyword
        sentences = re.split(r'(?<=[.!?])\s+', text)
        redacted = " ".join(
            s if keyword.lower() not in s.lower()
            else "[Content removed for safety]"
            for s in sentences
        )
        return redacted

    def is_safe(self, response: str) -> bool:
        """Quick safety check."""
        filtered, violations = self.filter(response)
        return len([v for v in violations if v.get("severity") == "high"]) == 0

    def get_report(self) -> dict[str, Any]:
        """Generate a safety filter report."""
        return {
            "total_violations": len(self.violations),
            "violations": self.violations,
            "categories_affected": list({v["category"] for v in self.violations}),
        }", "path": "/home/azureuser/fscompanion/src/gemma/safety_filters.py"}

