from typing import Any


class ResponseScorer:
    """Scores Gemma responses for relevance, safety, and helpfulness."""

    def __init__(self):
        self.weights = {
            "relevance": 0.30,
            "safety": 0.25,
            "helpfulness": 0.25,
            "tone_appropriateness": 0.10,
            "completeness": 0.10,
        }

    def score(self, response: str, expected_topics: list[str] | None = None) -> dict[str, Any]:
        """Score a response across multiple dimensions."""

        scores = {
            "relevance": self._score_relevance(response, expected_topics),
            "safety": self._score_safety(response),
            "helpfulness": self._score_helpfulness(response),
            "tone_appropriateness": self._score_tone(response),
            "completeness": self._score_completeness(response),
        }

        overall = sum(scores[k] * self.weights[k] for k in scores)

        return {
            "overall_score": round(overall, 3),
            "dimension_scores": {k: round(v, 3) for k, v in scores.items()},
            "grade": self._grade(overall),
            "recommendation": self._recommend(overall, scores),
        }

    def _score_relevance(self, response: str, topics: list[str] | None) -> float:
        if not topics:
            return 0.7  # Default assumption
        response_lower = response.lower()
        matched = sum(1 for t in topics if t.lower() in response_lower)
        return min(1.0, matched / max(1, len(topics)))

    def _score_safety(self, response: str) -> float:
        from src.gemma.safety_filters import SafetyFilter
        sf = SafetyFilter()
        _, violations = sf.filter(response)
        high_violations = len([v for v in violations if v.get("severity") == "high"])
        return max(0.0, 1.0 - high_violations * 0.5)

    def _score_helpfulness(self, response: str) -> float:
        positive_signals = [
            "here are some", "i recommend", "you can try",
            "consider", "would help", "suggest",
        ]
        negative_signals = [
            "i don't know", "i'm not sure", "can't help",
            "not my area", "cannot assist",
        ]
        response_lower = response.lower()
        pos = sum(1 for s in positive_signals if s in response_lower)
        neg = sum(1 for s in negative_signals if s in response_lower)
        return min(1.0, max(0.0, 0.5 + (pos - neg) * 0.15))

    def _score_tone(self, response: str) -> float:
        """Assess tone appropriateness (simplified heuristic)."""
        if not response.strip():
            return 0.0
        length = len(response.strip().split())
        if length < 20:
            return 0.5  # Too brief
        if length > 500:
            return 0.6  # Verbose
        return 0.85

    def _score_completeness(self, response: str) -> float:
        if not response.strip():
            return 0.0
        has_structure = any(c in response for c in ["\n", "•", "1.", "2.", "3."])
        has_actionable = any(w in response.lower() for w in ["you can", "try", "consider", "recommend"])
        score = 0.5
        if has_structure:
            score += 0.25
        if has_actionable:
            score += 0.25
        return min(1.0, score)

    def _grade(self, score: float) -> str:
        if score >= 0.85:
            return "A"
        elif score >= 0.70:
            return "B"
        elif score >= 0.55:
            return "C"
        elif score >= 0.40:
            return "D"
        return "F"

    def _recommend(self, score: float, scores: dict) -> str:
        if score >= 0.80:
            return "Response quality is good. No changes needed."
        weak = [k for k, v in scores.items() if v < 0.6]
        if weak:
            return f"Improve: {', '.join(weak)}. Consider regenerating with different parameters."
        return "Response is adequate but could be improved with more context."", "path": "/home/azureuser/fscompanion/src/gemma/response_scoring.py"}
